package com.tekwatt.support.entity;import jakarta.persistence.*;import java.time.Instant;import java.util.UUID;@Entity @Table(name="support_ticket_events")public class TicketEvent{@Id private UUID id;@Column(nullable=false)private UUID ticketId;@Column(nullable=false,length=40)private String eventType;@Column(name="from_value",length=120)private String fromValue;@Column(name="to_value",length=120)private String toValue;private UUID actorId;@Column(length=120)private String actorName;@Column(nullable=false,updatable=false)private Instant createdAt;protected TicketEvent(){}public TicketEvent(UUID t,String e,String f,String to,UUID a,String n){id=UUID.randomUUID();ticketId=t;eventType=e;fromValue=f;toValue=to;actorId=a;actorName=n;createdAt=Instant.now();}public UUID getId(){return id;}public UUID getTicketId(){return ticketId;}public String getEventType(){return eventType;}public String getFromValue(){return fromValue;}public String getToValue(){return toValue;}public UUID getActorId(){return actorId;}public String getActorName(){return actorName;}public Instant getCreatedAt(){return createdAt;}}
